entries.answer:
Itt van a módosított userscript, amely automatikusan magyarra fordít minden weboldalt:

javascript
// ==UserScript==
// @name         Automatikus magyar fordítás
// @namespace    https://staybrowser.com/
// @version      1.0
// @description  Automatikusan magyarra fordít minden weboldalt
// @author       You
// @match        *://*/*
// @grant        none
// ==/UserScript==

(function () {
    'use strict';

    // Google Translate elem létrehozása
    var translateDiv = document.createElement('div');
    translateDiv.id = 'google_translate_element';
    translateDiv.style.display = 'none';
    document.body.appendChild(translateDiv);

    // Google Translate inicializálása
    window.googleTranslateElementInit = function() {
        new google.translate.TranslateElement({
            pageLanguage: 'auto',
            includedLanguages: 'hu',
            autoDisplay: false
        }, 'google_translate_element');

        // Automatikus fordítás indítása
        setTimeout(function() {
            var selectElement = document.querySelector('#google_translate_element select');
            if (selectElement) {
                selectElement.value = 'hu';
                selectElement.dispatchEvent(new Event('change'));
            }
        }, 1000);
    };

    // Google Translate script betöltése
    var script = document.createElement('script');
    script.src = '//translate.google.com/translate_a/element.js?cb=googleTranslateElementInit';
    document.body.appendChild(script);

    // Fordítási sáv elrejtése CSS-sel
    var style = document.createElement('style');
    style.textContent = `
        body { top: 0 !important; }
        .skiptranslate, #google_translate_element { display: none !important; }
        .goog-te-banner-frame.skiptranslate { display: none !important; }
    `;
    document.head.appendChild(style);
})();


Ez a script a Google Translate beépített szolgáltatását használja a weboldalak automatikus fordításához. A script működése:[1]

 Automatikus nyelvfelismerés: A pageLanguage: 'auto' beállítás automatikusan felismeri az eredeti nyelvet[1]
 Magyar célnyelv: Az includedLanguages: 'hu' paraméter magyarra fordít[1]
 Láthatatlan működés: A fordító felület elrejtésre kerül CSSsel, így nem zavarja a böngészést[1]
 Azonnali fordítás: A setTimeout függvény 1 másodperc után automatikusan aktiválja a fordítást[1]

A script minden weboldalon (@match *://*/*) működik, és a Google Translate APIt használja a fordításhoz.[2]
